SOURCES={'protocol': '"""Strict non-executable package/report formats. Hashes are not signatures."""\n\nimport base64\nimport hashlib\nimport json\nimport pkgutil\nimport re\nimport struct\nimport zlib\n\nSIZE = 0x40000\nSTART, END = 0x100, 0x17FE0\nPROFILE = "ut3g-p25q21h-sp8516-r1-v1"\nFIRMWARE_SHA = "df52de4e874a2fc4063b83f4228182013f01f86aacd820243f777d8304755a3a"\nPRODUCTS = {"R4": "custom ed4e39b7-CLEAN", "UID-R1": "custom ed4e39b7-CLEAN", "SP8516-R1": "custom 8516b768-CLEAN"}\n\n\ndef sha(data):\n  return hashlib.sha256(data).hexdigest()\n\n\ndef canonical(value):\n  return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=True).encode()\n\n\ndef profile():\n  return {\'stable_wrapper_sha256\': \'99db5e2ec62c2b24124385ca7cbab2f9dd63872f773b7c92cb0c483bbc129af4\', \'uid_template_sha256\': \'04b4722952077751849bf44335b59c4e2bf6293332dea026e1851b1e77c298d0\', \'uid_offset\': 32444, \'uid_normalized_body_sha256\': \'310eaa44f011b08f87eb345eadfbdd69e02aea772a8dfa65d9c0bd4dc3153ff4\', \'reference_uid\': \'425030483334381610ad5a184c028278\', \'schema\': 1}\n\n\ndef unwrap(data):\n  if len(data) != END - START:\n    raise ValueError("只接受98016字节的已知固件槽，不接受整片或未知bin")\n  body = data[4:-6]\n  if (\n    struct.unpack_from("<I", data)[0] != len(body)\n    or data[-6:-4] != bytes((0xA5, sum(body) & 255))\n    or struct.unpack_from("<I", data, len(data) - 4)[0] != zlib.crc32(body) & 0xFFFFFFFF\n  ):\n    raise ValueError("固件封装长度/校验失败")\n  return body\n\n\ndef wrapper_kind(data, uid):\n  body = bytearray(unwrap(data))\n  if sha(data) == FIRMWARE_SHA:\n    return "SP8516-R1"\n  p = profile()\n  if sha(data) == p["stable_wrapper_sha256"]:\n    return "R4"\n  a = p["uid_offset"] - 4\n  if body[a : a + 16] != bytes.fromhex(uid):\n    raise ValueError("固件内 UID 与目标底座不一致")\n  body[a : a + 16] = bytes(16)\n  if sha(body) != p["uid_normalized_body_sha256"]:\n    raise ValueError("不是已批准的原版 R4 或仅 UID 个性化的 UID-R1")\n  return "UID-R1"\n\n\ndef validate_report(report):\n  if not isinstance(report, dict) or report.get("schema") != "ut3g-customer-report-v1" or report.get("profile") != PROFILE:\n    raise ValueError("不支持的客户报告")\n  uid = report.get("uid", "")\n  if not re.fullmatch(r"[0-9a-f]{32}", uid) or uid in ("00" * 16, "ff" * 16):\n    raise ValueError("无效硬件 UID")\n  if report.get("jedec") != "854012" or report.get("flash_size") != SIZE or report.get("reads") != 3 or report.get("persistent_writes") != 0:\n    raise ValueError("报告缺少受支持 Flash 身份或三读证据")\n  for key in ("full_sha256", "config_sha256", "outside_wrapper_sha256", "wrapper_sha256", "report_id"):\n    if not re.fullmatch(r"[0-9a-f]{64}", report.get(key, "")):\n      raise ValueError("报告哈希字段错误")\n  if sha(canonical({k: v for k, v in report.items() if k != "report_id"})) != report["report_id"]:\n    raise ValueError("报告校验失败")\n  return report\n\n\ndef make_report(uid, image, usb):\n  if len(image) != SIZE:\n    raise ValueError("不是完整 Flash")\n  wrapper = image[START:END]\n  kind = wrapper_kind(wrapper, uid)\n  report = {\n    "schema": "ut3g-customer-report-v1",\n    "profile": PROFILE,\n    "uid": uid,\n    "jedec": "854012",\n    "flash_size": SIZE,\n    "full_sha256": sha(image),\n    "config_sha256": sha(image[:START]),\n    "outside_wrapper_sha256": sha(image[:START] + image[END:]),\n    "wrapper_sha256": sha(wrapper),\n    "firmware": kind,\n    "reads": 3,\n    "persistent_writes": 0,\n    "config_serial": image[4:16].decode("ascii", errors="replace"),\n    "usb": usb,\n  }\n  report["report_id"] = sha(canonical(report))\n  return validate_report(report)\n\n\ndef make_package(report, wrapper, release):\n  validate_report(report)\n  kind = wrapper_kind(wrapper, report["uid"])\n  if not isinstance(release, str) or not 1 <= len(release) <= 80:\n    raise ValueError("版本名长度必须为1至80")\n  package = {\n    "schema": "ut3g-customer-package-v1",\n    "report": report,\n    "release": release,\n    "target_kind": kind,\n    "wrapper_b64": base64.b64encode(wrapper).decode(),\n    "wrapper_sha256": sha(wrapper),\n  }\n  package["package_id"] = sha(canonical(package))\n  return package\n\n\ndef validate_package(package):\n  if not isinstance(package, dict) or package.get("schema") != "ut3g-customer-package-v1":\n    raise ValueError("不是客户固件包")\n  if set(package) != {"schema", "report", "release", "target_kind", "wrapper_b64", "wrapper_sha256", "package_id"}:\n    raise ValueError("固件包字段不受支持")\n  validate_report(package["report"])\n  if sha(canonical({k: v for k, v in package.items() if k != "package_id"})) != package["package_id"]:\n    raise ValueError("固件包完整性校验失败")\n  if not isinstance(package["wrapper_b64"], str) or len(package["wrapper_b64"]) > 140000:\n    raise ValueError("固件大小无效")\n  wrapper = base64.b64decode(package["wrapper_b64"], validate=True)\n  if sha(wrapper) != package["wrapper_sha256"] or wrapper_kind(wrapper, package["report"]["uid"]) != package["target_kind"]:\n    raise ValueError("固件内容/UID不匹配")\n  return wrapper\n\n\ndef plan(package, uid, image):\n  wrapper = validate_package(package)\n  r = package["report"]\n  if (\n    uid != r["uid"]\n    or len(image) != SIZE\n    or sha(image) != r["full_sha256"]\n    or sha(image[:START]) != r["config_sha256"]\n    or sha(image[:START] + image[END:]) != r["outside_wrapper_sha256"]\n  ):\n    raise ValueError("换板或当前固件/配置已变化，请重新采集报告")\n  source_kind = wrapper_kind(image[START:END], uid)\n  if source_kind != "SP8516-R1" and package["target_kind"] != "SP8516-R1":\n    raise ValueError("仅支持升级至SP8516-R1或从它回退")\n  target = image[:START] + wrapper + image[END:]\n  sectors = [i for i in range(64) if image[i * 4096 : (i + 1) * 4096] != target[i * 4096 : (i + 1) * 4096]]\n  if not set(sectors) <= {7, 8, 13, 14, 15, 23}:\n    raise ValueError("变化超出固定候选的loader/压缩容器/校验扇区")\n  result = {\n    "uid": uid,\n    "package_id": package["package_id"],\n    "source_sha256": sha(image),\n    "target_sha256": sha(target),\n    # Write the compressed runtime first and its validating loader last.\n    "sectors": [s for s in (15, 14, 13, 23, 8, 7) if s in sectors],\n    "release": package["release"],\n    "kind": package["target_kind"],\n    "recovery_guaranteed": False,\n  }\n  result["confirmation"] = sha(canonical(result))\n  return result, target\n', 'spi_core': '# Generated from the hash-pinned, hardware-exercised SPI engine.\nimport ctypes as C\nimport time\n\nCFG = (0xC8AD, 0xC8AE, 0xC8AF, 0xC8AA, 0xC8AC, 0xC8A1, 0xC8A2, 0xC8AB, 0xC8A3, 0xC8A4, 0xC8A6, 0xCA81)\n\nREAD_OPS = {3, 5, 0x35, 0x15, 0x9F, 0x4B}\n\nWRITE_OPS = {4, 6, 0x50, 1, 2, 0x20}\n\nclass Ctrl(C.Structure):\n  _fields_ = [\n    ("bm", C.c_uint8),\n    ("req", C.c_uint8),\n    ("value", C.c_uint16),\n    ("index", C.c_uint16),\n    ("length", C.c_uint16),\n    ("timeout", C.c_uint32),\n    ("data", C.c_void_p),\n  ]\n\nclass SPI:\n  def __init__(self, transport):\n    self.transport = transport\n    self.enabled = False\n    self.owned_wel = False\n    self.saved = {}\n    self.dirty_protection = False\n    self.trigger_attempted = None\n    self.persistent_attempts = []\n    self.allowed_sectors = set()\n    self.touched = False\n\n  def rd(self, address, length=1):\n    registers = set(CFG) | {0xC8A9, 0xC8B6, 0xC8B8, 0xC8D6, 0xB450}\n    if not ((address in registers and length == 1) or (0x7000 <= address and 1 <= length <= 255 and address + length <= 0x8000)):\n      raise ValueError("E4 address outside install allowlist")\n    return self.transport.control(False, address, length=length)\n\n  def wr(self, address, value):\n    if not 0 <= value <= 255 or address not in set(CFG) | {0xC8A9, 0xCC33, 0xC805} and not 0x7000 <= address < 0x7080:\n      raise ValueError("E5 address outside install allowlist")\n    self.touched = True\n    self.transport.control(True, address, value)\n\n  def idle(self, timeout=3):\n    deadline = time.monotonic() + timeout\n    while time.monotonic() < deadline:\n      if not self.rd(0xC8A9)[0] & 1 and not self.rd(0xC8B6)[0] & 0x80 and not self.rd(0xC8B8)[0] & 1:\n        self.trigger_attempted = None\n        return\n      time.sleep(0.001)\n    raise RuntimeError("SPI engine unresolved; no new transaction/retry")\n\n  def txn(self, op, address=0, length=0, mode=0):\n    if op not in READ_OPS | WRITE_OPS or op in WRITE_OPS and not self.enabled:\n      raise RuntimeError("SPI operation not authorized")\n    if op == 3 and not (0 <= address < 0x40000 and 1 <= length <= 4096 and address + length <= 0x40000):\n      raise ValueError("invalid Flash read span")\n    if op in (2, 0x20) and (\n      address // 4096 not in self.allowed_sectors\n      or (op == 0x20 and (address % 4096 or length or mode))\n      or (op == 2 and (address % 128 or length != 128 or mode != 1))\n    ):\n      raise ValueError("erase/program outside reviewed sector/page geometry")\n    if op == 1 and (mode != 1 or length != 1):\n      raise ValueError("invalid volatile protection write")\n    if self.rd(0xC8D6)[0] & 8:\n      raise RuntimeError("SPI DMA error; refuse transaction")\n    self.idle()\n    fields = (\n      (0xC8AD, mode),\n      (0xC8AE, 0),\n      (0xC8AF, 0),\n      (0xC8AA, op),\n      (0xC8AC, 7 if op in (2, 3, 0x20) else 4),\n      (0xC8A1, address & 255),\n      (0xC8A2, address >> 8 & 255),\n      (0xC8AB, address >> 16 & 255),\n      (0xC8A3, length >> 8),\n      (0xC8A4, length & 255),\n    )\n    for reg, value in fields:\n      self.wr(reg, value)\n      if self.rd(reg)[0] != value:\n        raise RuntimeError("SPI setup readback mismatch; no trigger")\n    if op in (1, 2, 0x20):\n      self.persistent_attempts.append((op, address))\n    if op == 6:\n      self.owned_wel = True\n    self.trigger_attempted = op\n    self.wr(0xC8A9, 1)  # no automatic retry even if ACK is lost\n    self.idle()\n    if self.rd(0xC8D6)[0] & 8:\n      raise RuntimeError("SPI DMA error after trigger")\n    for _ in range(4):\n      self.wr(0xC8AD, 0)\n    if op in READ_OPS:\n      return b"".join(self.rd(0x7000 + i, min(255, length - i)) for i in range(0, length, 255))\n    return b""\n\n  def statuses(self):\n    return bytes(self.txn(op, length=1)[0] for op in (5, 0x35, 0x15))\n\n  def wait_wip(self):\n    deadline = time.monotonic() + 12\n    while time.monotonic() < deadline:\n      value = self.txn(5, length=1)[0]\n      if not value & 1:\n        if not value & 2:\n          self.owned_wel = False\n        return value\n      time.sleep(0.002)\n    raise RuntimeError("Flash WIP unresolved; do not resend writes")\n\n  def read(self, address=0, length=0x40000):\n    return b"".join(self.txn(3, address + i, min(4096, length - i)) for i in range(0, length, 4096))\n\n  def uid(self):\n    return self.txn(0x4B, length=20)[4:].hex()\n\n  def snapshot(self):\n    self.idle()\n    self.saved = {r: self.rd(r)[0] for r in CFG}\n    if self.saved[0xC8AD] or self.saved[0xC8A6] != 4:\n      raise RuntimeError("unexpected live SPI mode/divider")\n\n  def buffer(self, data):\n    if not 1 <= len(data) <= 128:\n      raise ValueError("invalid TX buffer size")\n    for i, value in enumerate(data):\n      self.wr(0x7000 + i, value)\n    if self.rd(0x7000, len(data)) != data:\n      raise RuntimeError("CPU page buffer readback failed; no Flash program trigger")\n\n  def protection(self, value):\n    if self.wait_wip() & 2:\n      raise RuntimeError("WEL must be clear before volatile WRSR")\n    self.buffer(bytes([value]))\n    self.txn(0x50)\n    self.txn(1, length=1, mode=1)  # never 06->01\n    if self.wait_wip() != value:\n      raise RuntimeError("volatile protection readback failed")\n\n  def unlock(self, order):\n    self.enabled = True\n    self.allowed_sectors = set(order)\n    self.wr(0xCC33, 4)\n    self.wr(0xCA81, self.rd(0xCA81)[0] | 1)\n    self.wr(0xC805, 2)\n    self.wr(0xC8A6, 4)\n    self.dirty_protection = True  # set before an ambiguous status operation\n    self.protection(0)\n    if self.statuses() != bytes.fromhex("000020"):\n      raise RuntimeError("unexpected unlocked status profile")\n\n  def wren(self):\n    if self.wait_wip() != 0:\n      raise RuntimeError("unexpected status before WREN")\n    self.txn(6)\n    if self.txn(5, length=1)[0] != 2:\n      raise RuntimeError("WEL did not set")\n\n  def erase(self, address):\n    self.wren()\n    self.txn(0x20, address)\n    if self.wait_wip() != 0 or self.read(address, 4096) != b"\\xff" * 4096:\n      raise RuntimeError("erase readback failed")\n\n  def program(self, address, data):\n    self.transport.offroad()\n    self.wren()\n    self.buffer(data)  # all status reads are BEFORE loading the page\n    self.txn(2, address, 128, 1)\n    if self.wait_wip() != 0 or self.read(address, 128) != data:\n      raise RuntimeError("page readback failed; no blind retry")\n\n  def cleanup(self):\n    if not self.touched:\n      return\n    self.idle(timeout=12)\n    if self.enabled:\n      status = self.wait_wip()\n      if status & 2:\n        if not self.owned_wel:\n          raise RuntimeError("unknown WEL ownership; cannot restore")\n        self.txn(4)\n        if self.wait_wip() & 2:\n          raise RuntimeError("WRDI failed")\n    if self.dirty_protection:\n      if self.statuses()[0] != 0x1C:\n        self.protection(0x1C)\n      if self.statuses() != bytes.fromhex("1c0020"):\n        raise RuntimeError("protection restoration not established")\n      self.dirty_protection = False\n    for reg in reversed(CFG):\n      if reg in self.saved and self.rd(reg)[0] != self.saved[reg]:\n        self.wr(reg, self.saved[reg])\n    if any(self.rd(r)[0] != v for r, v in self.saved.items()):\n      raise RuntimeError("volatile register restoration mismatch")\n', 'service': '"""Collect, preflight and one-shot flash. No arbitrary commands from packages."""\n\nimport os\nfrom pathlib import Path\nimport time\nimport shutil\nimport struct\n\nfrom . import protocol as p\n\n\ndef save(path, data):\n  path = Path(path)\n  fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)\n  with os.fdopen(fd, "wb") as f:\n    f.write(data)\n    f.flush()\n    os.fsync(f.fileno())\n  directory = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)\n  try:\n    os.fsync(directory)\n  finally:\n    os.close(directory)\n\n\ndef emit(folder, event):\n  data = p.canonical({"monotonic_s": time.monotonic(), **event}) + b"\\n"\n  fd = os.open(Path(folder) / "events.jsonl", os.O_WRONLY | os.O_CREAT | os.O_APPEND | os.O_NOFOLLOW, 0o600)\n  try:\n    os.write(fd, data)\n    os.fsync(fd)\n  finally:\n    os.close(fd)\n\n\ndef capture(spi, folder):\n  spi.transport.guard()\n  spi.snapshot()\n  if spi.txn(0x9F, length=3) != bytes.fromhex("854012") or spi.statuses() != bytes.fromhex("1c0020"):\n    raise RuntimeError("Flash型号或保护状态不在支持范围，不清除保护位")\n  uids = [spi.uid() for _ in range(3)]\n  if len(set(uids)) != 1 or uids[0] in ("00" * 16, "ff" * 16):\n    raise RuntimeError("UID三读不一致或无效")\n  image = None\n  for i in range(3):\n    spi.transport.guard()\n    current = spi.read()\n    if len(current) != p.SIZE or image is not None and image != current:\n      raise RuntimeError("整片三读不一致，不生成可刷写报告")\n    image = current\n    emit(folder, {"stage": "read", "read": i + 1, "sha256": p.sha(current)})\n  if spi.statuses() != bytes.fromhex("1c0020"):\n    raise RuntimeError("读取后保护状态变化")\n  # Backup precedes any future WREN/erase; customer-side only, not in report.\n  save(Path(folder) / "backup.bin", image)\n  return uids[0], image\n\n\ndef operation(kind, folder, *, package=None, expected=None, confirmed=False, session_factory=None):\n  if kind not in ("collect", "prepare", "flash", "verify"):\n    raise ValueError("unknown operation")\n  if kind == "flash" and (not confirmed or not isinstance(expected, dict)):\n    raise ValueError("必须由客户确认目标UID/版本与断电风险后才可刷写")\n  if kind in ("prepare", "flash"):\n    p.validate_package(package)  # Reject malformed data before opening USB.\n  if session_factory is None:\n    from .hardware import Session\n\n    session_factory = Session\n  folder = Path(folder)\n  folder.mkdir(mode=0o700, parents=True, exist_ok=False)\n  report = {"status": "STARTED", "operation": kind, "written_sectors": [], "reset_sent": False}\n  try:\n    if shutil.disk_usage(folder).free < 8 * 1024 * 1024:\n      raise RuntimeError("磁盘剩余空间不足8MiB，无法保证备份与日志，拒绝访问设备")\n    with session_factory() as spi:\n      try:\n        uid, image = capture(spi, folder)\n        if kind == "collect":\n          usb = {k: v for k, v in getattr(spi.transport, "identity", {}).items() if k in ("product", "serial", "speed")}\n          enrollment = p.make_report(uid, image, usb)\n          save(folder / "report.json", p.canonical(enrollment))\n          report.update(status="REPORT_READY", uid=uid, report=enrollment)\n        elif kind == "verify":\n          if uid != expected["uid"] or p.sha(image) != expected["target_sha256"]:\n            raise RuntimeError("重新上电后的UID/固件与已写入目标不一致")\n          actual_kind = p.wrapper_kind(image[p.START : p.END], uid)\n          product = spi.transport.identity["product"]\n          if product != p.PRODUCTS[actual_kind]:\n            raise RuntimeError("Flash读回匹配，但USB仍是旧运行身份；完整断电上电后再核验")\n          link = spi.rd(0xB450).hex()\n          c2 = spi.transport.runtime_read(0xC2, 8)\n          c0 = spi.transport.runtime_read(0xC0, 5 if actual_kind == "SP8516-R1" else 4)\n          voltage, current = struct.unpack("<Hh", c0[:4])\n          fault = bool(c0[4]) if len(c0) == 5 else None\n          ready = link == "78" and c2[0] == 1 and c2[1] == c2[4] == 0\n          if actual_kind == "SP8516-R1":\n            ready = ready and voltage >= 5000 and not fault\n          report.update(\n            status="POSTBOOT_FIRMWARE_VERIFIED" if ready else "POSTBOOT_FIRMWARE_VERIFIED_RUNTIME_NOT_READY",\n            firmware_verified=True,\n            runtime_ready=ready,\n            uid=uid,\n            target_sha256=p.sha(image),\n            product=product,\n            pcie_b450=link,\n            c2_hex=c2.hex(),\n            supply_voltage_mv=voltage,\n            supply_current_ma=current,\n            supply_fault=fault,\n            model_validated=False,\n          )\n        else:\n          proposed, target = p.plan(package, uid, image)\n          report["plan"] = proposed\n          save(folder / "plan.json", p.canonical(proposed))\n          if kind == "prepare":\n            report["status"] = "PREFLIGHT_READY"\n          else:\n            if proposed != expected:\n              raise RuntimeError("预检后计划发生变化，请重新采集，不能沿用确认")\n            save(folder / "intent.json", p.canonical({"plan": proposed, "accepted_power_loss_risk": True}))\n            save(folder / "expected.bin", target)\n            if proposed["sectors"]:\n              spi.transport.guard()\n              spi.unlock(proposed["sectors"])\n              for n, sector in enumerate(proposed["sectors"]):\n                spi.transport.guard()\n                a = sector * 4096\n                if spi.read(a, 4096) != image[a : a + 4096]:\n                  raise RuntimeError("写入前扇区发生变化，停止")\n                emit(folder, {"stage": "sector_start", "sector": sector, "index": n + 1, "total": len(proposed["sectors"])})\n                spi.erase(a)\n                for offset in range(0, 4096, 128):\n                  spi.program(a + offset, target[a + offset : a + offset + 128])\n                if spi.read(a, 4096) != target[a : a + 4096]:\n                  raise RuntimeError("扇区核验失败，停止，不重试")\n                report["written_sectors"].append(sector)\n                emit(folder, {"stage": "sector_verified", "sector": sector})\n            for i in range(3):\n              spi.transport.guard()\n              if spi.read() != target:\n                raise RuntimeError("最终整片核验失败，停止")\n              emit(folder, {"stage": "final_read", "read": i + 1, "sha256": p.sha(target)})\n            if spi.uid() != uid:\n              raise RuntimeError("最终UID变化")\n            report["status"] = "WRITTEN_VERIFIED_PENDING_POWER_CYCLE" if proposed["sectors"] else "ALREADY_TARGET_NO_WRITE"\n      finally:\n        report["protection_and_registers_restored"] = False\n        report["persistent_attempts"] = spi.persistent_attempts\n        try:\n          spi.cleanup()\n          report["protection_and_registers_restored"] = True\n        except Exception as error:\n          report["cleanup_error"] = str(error)\n          raise\n  except Exception as error:\n    report.update(status="FAILED_STOPPED", error=str(error))\n    if (folder / "intent.json").exists():\n      report["warning"] = "写入已开始或可能开始：不要自动重试或断电，保留备份和日志联系提供方；可能需要外部SPI恢复。"\n  save(folder / "result.json", p.canonical(report))\n  return report\n', 'commands': '"""Standalone BIN installation; persistent writes run in a detached worker."""\n\nimport argparse\nimport json\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\nimport uuid\n\nfrom . import protocol as p\nfrom .service import operation, save\n\nBUNDLE_SCRIPT = None\nFIRMWARE = None\n\n\ndef read_json(path):\n  with path.open(\'rb\') as f:\n    data = f.read(200001)\n  if len(data) > 200000:\n    raise ValueError(\'状态/任务文件超过200KB\')\n  return json.loads(data)\n\n\ndef atomic_json(path, value):\n  temp = path.with_name(path.name + \'.\' + uuid.uuid4().hex)\n  save(temp, p.canonical(value))\n  os.replace(temp, path)\n  fd = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)\n  try:\n    os.fsync(fd)\n  finally:\n    os.close(fd)\n\n\ndef show(value):\n  print(json.dumps(value, ensure_ascii=False, indent=2), flush=True)\n\n\ndef firmware(path):\n  if path.is_symlink():\n    raise ValueError(\'固件文件不能是符号链接\')\n  with path.open(\'rb\') as f:\n    data = f.read(p.END - p.START + 1)\n  p.unwrap(data)\n  if p.sha(data) != p.FIRMWARE_SHA:\n    raise ValueError(\'固件不是本安装器固定支持的SP8516-R1，拒绝打开设备\')\n  return data\n\n\ndef main():\n  parser = argparse.ArgumentParser(description=\'直接刷入现成UT3G SP8516-R1 BIN；不编译，不改SP/tinygrad\')\n  parser.add_argument(\'action\', nargs=\'?\', default=\'check\', choices=(\'check\', \'install\', \'verify\', \'status\', \'rollback\', \'worker\'))\n  parser.add_argument(\'--firmware\', type=Path, default=FIRMWARE)\n  parser.add_argument(\'--state\', type=Path, default=Path(\'/data/ut3g-sp8516\'))\n  parser.add_argument(\'--job\', type=Path, help=argparse.SUPPRESS)\n  args = parser.parse_args()\n  if args.action == \'check\':\n    data = firmware(args.firmware)\n    show(\n      {\n        \'status\': \'FILE_CHECK_PASS\',\n        \'bytes\': len(data),\n        \'sha256\': p.sha(data),\n        \'requires_compiler\': False,\n        \'sp_modified\': False,\n        \'tinygrad_modified\': False,\n        \'firmware_hardware_validated\': False,\n      }\n    )\n    return 0\n  if args.action == \'status\':\n    if not (args.state / \'last.json\').is_file():\n      show({\'status\': \'NO_JOB\', \'state\': str(args.state)})\n      return 0\n    job = Path(read_json(args.state / \'last.json\')[\'job\'])\n    show(\n      {\n        \'job\': str(job),\n        \'pending\': (args.state / \'pending.json\').exists(),\n        \'result\': read_json(job / \'run/result.json\') if (job / \'run/result.json\').is_file() else \'RUNNING_OR_INTERRUPTED\',\n        \'verified\': read_json(job / \'verified.json\') if (job / \'verified.json\').is_file() else None,\n      }\n    )\n    return 0\n  if sys.platform != \'linux\' or os.geteuid() != 0:\n    raise RuntimeError(\'请在停车的C3 Linux上用sudo python3运行；Windows/macOS可运行check\')\n  args.state = args.state.resolve()\n  args.state.mkdir(mode=0o700, parents=True, exist_ok=True)\n  if args.action == \'worker\':\n    if args.job is None or args.job.resolve().parent != args.state:\n      raise ValueError(\'非法内部任务路径\')\n    if Path(read_json(args.state / \'pending.json\')[\'job\']) != args.job:\n      raise ValueError(\'缺少匹配的一次性pending意图\')\n    job = read_json(args.job / \'job.json\')\n    result = operation(\'flash\', args.job / \'run\', package=job[\'package\'], expected=job[\'plan\'], confirmed=True)\n    show(result)\n    return 0 if result[\'status\'] in (\'WRITTEN_VERIFIED_PENDING_POWER_CYCLE\', \'ALREADY_TARGET_NO_WRITE\') else 2\n\n  import fcntl\n\n  lock = os.open(args.state / \'command.lock\', os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)\n  try:\n    fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)\n    return operate(args)\n  finally:\n    os.close(lock)\n\n\ndef operate(args):\n  state = args.state\n  if args.action == \'verify\':\n    job = Path(read_json(state / \'last.json\')[\'job\'])\n    result = read_json(job / \'run/result.json\')\n    if result[\'status\'] not in (\'WRITTEN_VERIFIED_PENDING_POWER_CYCLE\', \'ALREADY_TARGET_NO_WRITE\'):\n      raise RuntimeError(\'上次任务未成功写完；禁止当作冷启动核验或自动重试\')\n    if result[\'status\'] != \'ALREADY_TARGET_NO_WRITE\' and input(\'确认已完整切断底座USB和外部供电再上电，输入 YES：\').strip() != \'YES\':\n      return 1\n    verify_dir = state / (\'verify-\' + uuid.uuid4().hex)\n    verified = operation(\'verify\', verify_dir, expected=result[\'plan\'])\n    show(verified)\n    if not verified.get(\'firmware_verified\') or not verified[\'protection_and_registers_restored\']:\n      return 2\n    atomic_json(job / \'verified.json\', {\'directory\': str(verify_dir), \'target_sha256\': verified[\'target_sha256\'], \'runtime_ready\': verified[\'runtime_ready\']})\n    pending = state / \'pending.json\'\n    if pending.exists():\n      if Path(read_json(pending)[\'job\']) != job:\n        raise RuntimeError(\'pending属于另一任务，拒绝清除\')\n      pending.unlink()\n      fd = os.open(state, os.O_RDONLY | os.O_DIRECTORY)\n      try:\n        os.fsync(fd)\n      finally:\n        os.close(fd)\n    print(\'固件及运行身份核验通过；模型/Windows/热插拔未由本工具验证。\', flush=True)\n    return 0 if verified[\'runtime_ready\'] else 3\n\n  if (state / \'pending.json\').exists():\n    raise RuntimeError(\'存在未核验或失败的任务；先status查看，成功写完才可断电后verify。不要删pending绕过\')\n  original_job = None\n  if args.action == \'install\':\n    wrapper = firmware(args.firmware)\n  else:\n    original_job = Path(read_json(state / \'last.json\')[\'job\'])\n    original = read_json(original_job / \'job.json\')\n    if original[\'action\'] != \'install\' or not (original_job / \'verified.json\').is_file():\n      raise RuntimeError(\'回退需要本工具已完成冷启动核验的安装记录\')\n    backup = (original_job / \'run/backup.bin\').read_bytes()\n    if len(backup) != p.SIZE or p.sha(backup) != original[\'plan\'][\'source_sha256\']:\n      raise ValueError(\'本次安装前备份的长度/哈希不匹配\')\n    wrapper = backup[p.START : p.END]\n    if p.wrapper_kind(wrapper, original[\'plan\'][\'uid\']) == \'SP8516-R1\':\n      raise ValueError(\'原来已是同一新版，没有可恢复的旧固件\')\n\n  folder = state / (\'collect-\' + uuid.uuid4().hex)\n  collected = operation(\'collect\', folder)\n  if collected[\'status\'] != \'REPORT_READY\':\n    show(collected)\n    return 2\n  report = collected[\'report\']\n  image = (folder / \'backup.bin\').read_bytes()\n  if original_job is not None:\n    if report[\'uid\'] != original[\'plan\'][\'uid\'] or report[\'full_sha256\'] != original[\'plan\'][\'target_sha256\']:\n      raise ValueError(\'当前底座/固件不是该安装记录的目标，禁止使用该备份回退\')\n    if image[: p.START] != backup[: p.START] or image[p.END :] != backup[p.END :]:\n      raise ValueError(\'当前配置/尾部与原备份不同，停止回退\')\n  package = p.make_package(report, wrapper, \'SP8516-R1\' if args.action == \'install\' else \'RESTORE-ORIGINAL\')\n  plan, target = p.plan(package, report[\'uid\'], image)\n  if original_job is not None and plan[\'target_sha256\'] != original[\'plan\'][\'source_sha256\']:\n    raise ValueError(\'回退目标不是原始完整备份\')\n  show(\n    {\n      \'action\': args.action,\n      \'uid\': report[\'uid\'],\n      \'config_serial\': report[\'config_serial\'],\n      \'source_firmware\': report[\'firmware\'],\n      \'target_firmware\': plan[\'kind\'],\n      \'sectors\': plan[\'sectors\'],\n      \'source_sha256\': plan[\'source_sha256\'],\n      \'target_sha256\': plan[\'target_sha256\'],\n      \'backup\': str(folder / \'backup.bin\'),\n    }\n  )\n  if plan[\'sectors\']:\n    print(\'这是未上板验收的候选固件；供电/I2C及GPU运行尚未验证。保持停车和稳定供电，失败可能需外部SPI恢复。\', flush=True)\n    if input(\'确认本板写入，输入 FLASH-\' + plan[\'uid\'][-8:] + \'：\').strip() != \'FLASH-\' + plan[\'uid\'][-8:]:\n      print(\'已取消，零擦写。\', flush=True)\n      return 1\n  elif (state / \'last.json\').exists():\n    previous = Path(read_json(state / \'last.json\')[\'job\'])\n    if read_json(previous / \'job.json\')[\'plan\'][\'target_sha256\'] == plan[\'target_sha256\']:\n      print(\'ALREADY_TARGET_NO_WRITE：目标一致，保留原安装及回退记录。\', flush=True)\n      return 0\n\n  job = state / (\'job-\' + uuid.uuid4().hex)\n  job.mkdir(mode=0o700)\n  save(job / \'job.json\', p.canonical({\'action\': args.action, \'package\': package, \'plan\': plan}))\n  if not plan[\'sectors\']:\n    (job / \'run\').mkdir(mode=0o700)\n    save(job / \'run/backup.bin\', image)\n    save(job / \'run/result.json\', p.canonical({\'status\': \'ALREADY_TARGET_NO_WRITE\', \'plan\': plan}))\n    atomic_json(state / \'last.json\', {\'job\': str(job)})\n    print(\'ALREADY_TARGET_NO_WRITE：零擦写，可直接运行verify，不必为本次操作断电。\', flush=True)\n    return 0\n  save(state / \'pending.json\', p.canonical({\'job\': str(job), \'plan\': plan}))\n  atomic_json(state / \'last.json\', {\'job\': str(job)})\n  with (job / \'worker.log\').open(\'xb\', buffering=0) as log:\n    worker = subprocess.Popen(\n      [sys.executable, BUNDLE_SCRIPT, \'worker\', \'--job\', str(job), \'--state\', str(state)],\n      stdin=subprocess.DEVNULL,\n      stdout=log,\n      stderr=log,\n      start_new_session=True,\n    )\n  print(f"独立worker已启动，PID {worker.pid}；SSH断开可重新运行status查看。日志：{job / \'worker.log\'}", flush=True)\n  worker.wait()\n  result = read_json(job / \'run/result.json\')\n  show(result)\n  if result[\'status\'] == \'WRITTEN_VERIFIED_PENDING_POWER_CYCLE\':\n    print(\'写入与三读核验完成。保持comma.service停止；完整断电上电后运行verify。\', flush=True)\n    return 0\n  return 2\n', 'hardware': '"""C3 Linux EP0 transport; require an explicit parked maintenance window."""\n\nimport ctypes as C\nimport fcntl\nimport json\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\nimport time\n\nfrom .spi_core import Ctrl, SPI\nfrom .protocol import PRODUCTS\n\nSYSFS = Path(\'/sys/bus/usb/devices\')\nPARAMS = Path(\'/data/params/d\')\n\n\ndef offroad():\n  observed = {}\n  for key in (\'IsOffroad\', \'IsOnroad\', \'IsEngaged\'):\n    try:\n      observed[key] = (PARAMS / key).read_bytes().strip()\n    except FileNotFoundError:\n      pass\n  if any(v not in (b\'0\', b\'1\') for v in observed.values()):\n    raise RuntimeError(\'行驶状态格式未知，拒绝操作\')\n  if observed.get(\'IsOffroad\') == b\'0\' or observed.get(\'IsOnroad\') == b\'1\' or observed.get(\'IsEngaged\') == b\'1\':\n    raise RuntimeError(\'当前Onroad/接管，拒绝操作\')\n  if observed.get(\'IsOffroad\') != b\'1\' and observed.get(\'IsOnroad\') != b\'0\':\n    raise RuntimeError(\'缺少可确认Offroad状态；不得伪造参数绕过\')\n\n\nIDENTITY_FILE = Path(\'/data/ut3g-install/identity.json\')\n\n\ndef _expected_identities():\n  """[ADAPTED] 身份白名单改为数据驱动，但仍是精确匹配。\n\n  原版硬编码 (\'3801\', \'0001\', \'tiny\', \'5000\')。本机底座是第三方 ASM2464，\n  manufacturer/speed 与硬编码值不同 -> candidates() 恒空 -> 安装器连设备都不打开。\n  这里从 identity.json 读白名单（由 ut3g_precheck.py --emit-identity 实测生成）。\n\n  刻意不做的事：不做前缀/通配/正则放宽，不跳过 JEDEC、保护位、扇区、三读、\n  备份时序、写入顺序等任何安全约束。白名单里的每一项都必须是实测到的完整值。\n  """\n  if not IDENTITY_FILE.is_file():\n    raise RuntimeError(\'缺少 \' + str(IDENTITY_FILE) + \'；先运行 ut3g_precheck.py --emit-identity\')\n  try:\n    spec = json.loads(IDENTITY_FILE.read_bytes())\n  except (OSError, ValueError) as error:\n    raise RuntimeError(\'identity.json 无法解析：\' + str(error))\n  if spec.get(\'schema\') != \'ut3g-adapted-identity-v1\':\n    raise RuntimeError(\'identity.json schema 不受支持，拒绝在未知白名单下操作\')\n  idents = {tuple(x) for x in spec.get(\'identities\', []) if isinstance(x, list) and len(x) == 4}\n  products = {x for x in spec.get(\'products\', []) if isinstance(x, str) and x}\n  if not idents or not products:\n    raise RuntimeError(\'identity.json 白名单为空，拒绝操作\')\n  return idents, products\n\n\ndef candidates(root=SYSFS):\n  found = []\n  idents, products = _expected_identities()\n  for path in sorted(root.iterdir()):\n    try:\n      fields = {n: (path / n).read_text().strip() for n in (\'idVendor\', \'idProduct\', \'manufacturer\', \'product\', \'serial\', \'speed\', \'busnum\', \'devnum\')}\n    except (OSError, UnicodeError):\n      continue\n    identity = (fields[\'idVendor\'], fields[\'idProduct\'], fields[\'manufacturer\'], fields[\'speed\'])\n    if identity in idents and fields[\'product\'] in products:\n      found.append((path, fields))\n  return found\n\n\nclass Session:\n  def __enter__(self):\n    self.fd = self.lock = None\n    self.deadline = time.monotonic() + 600\n    try:\n      if sys.platform != \'linux\' or os.geteuid() != 0 or C.sizeof(Ctrl) != 24:\n        raise RuntimeError(\'请在C3 Linux使用sudo python3运行\')\n      offroad()\n      self.lock = os.open(\'/run/lock/ut3g-customer.lock\', os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)\n      fcntl.flock(self.lock, fcntl.LOCK_EX | fcntl.LOCK_NB)\n      items = candidates()\n      if len(items) != 1:\n        raise RuntimeError(\'需要恰好一块受支持的RAW USB3底座；原厂/ROM/未知/多底座不自动处理\')\n      self.path, self.identity = items[0]\n      self.node = f"/dev/bus/usb/{int(self.identity[\'busnum\']):03d}/{int(self.identity[\'devnum\']):03d}"\n      self.guard()\n      self.fd = os.open(self.node, os.O_RDWR | os.O_NOFOLLOW)\n      self.spi = SPI(self)\n      return self.spi\n    except BaseException:\n      self.__exit__()\n      raise\n\n  def offroad(self):\n    offroad()\n    if time.monotonic() > self.deadline:\n      raise RuntimeError(\'维护操作超过600秒，停止新事务\')\n\n  def guard(self):\n    self.offroad()\n    service = subprocess.run([\'systemctl\', \'is-active\', \'comma.service\'], capture_output=True, text=True, timeout=3)\n    if service.returncode != 3 or service.stdout.strip() != \'inactive\':\n      raise RuntimeError(\'comma.service未确认inactive；停车后先停止服务，不修改SP代码\')\n    if any((self.path / n).read_text().strip() != v for n, v in self.identity.items()):\n      raise RuntimeError(\'USB身份或连接周期变化，拒绝自动重连\')\n    owners = subprocess.run([\'fuser\', self.node], capture_output=True, text=True, timeout=3)\n    if owners.returncode not in (0, 1) or set(owners.stdout.split()) - {str(os.getpid())}:\n      raise RuntimeError(\'USB仍被其他进程使用；先退出statusd/GPU使用者，不争抢\')\n\n  def control(self, write, address, value=0, length=1):\n    buf = C.create_string_buffer(max(1, length))\n    ctl = Ctrl(0x40 if write else 0xC0, 0xE5 if write else 0xE4, address, value, 0 if write else length, 2000, C.addressof(buf))\n    count = fcntl.ioctl(self.fd, 0xC0185500, ctl)\n    if count != (0 if write else length):\n      raise RuntimeError(\'USB响应长度错误，停止且不重试\')\n    return None if write else buf.raw[:length]\n\n  def runtime_read(self, request, length):\n    if (request, length) not in ((0xC0, 4), (0xC0, 5), (0xC2, 8)):\n      raise ValueError(\'只允许C0/C2状态读取\')\n    self.guard()\n    buf = C.create_string_buffer(length)\n    ctl = Ctrl(0xC0, request, 0, 0, length, 2000, C.addressof(buf))\n    if fcntl.ioctl(self.fd, 0xC0185500, ctl) != length:\n      raise RuntimeError(\'运行状态长度错误，不能认定核验通过\')\n    return buf.raw\n\n  def __exit__(self, *_):\n    try:\n      if self.fd is not None:\n        os.close(self.fd)\n        self.fd = None\n    finally:\n      if self.lock is not None:\n        os.close(self.lock)\n        self.lock = None\n'}

def load_modules(with_hardware=False):
  root=types.ModuleType('ut3g_sp8516');root.__path__=[];sys.modules[root.__name__]=root
  for name,source in SOURCES.items():
    if name=='hardware' and not with_hardware:continue
    module=types.ModuleType(root.__name__+'.'+name);module.__package__=root.__name__
    sys.modules[module.__name__]=module;setattr(root,name,module)
    exec(compile(source,'<bundled '+name+'>','exec'),module.__dict__)
  return root

if __name__=='__main__':
  from pathlib import Path
  root=load_modules(sys.platform=='linux')
  root.commands.BUNDLE_SCRIPT=str(Path(__file__).resolve())
  root.commands.FIRMWARE=Path(__file__).resolve().with_name('UT3G_SP8516_UNBOUND_R1.bin')
  try:
    raise SystemExit(root.commands.main())
  except (RuntimeError,ValueError,OSError) as error:
    print('STOPPED: '+str(error),file=sys.stderr)
    raise SystemExit(2)
